    for line in f:
        o=json.loads(line)
        if o.get('scenario')=='stock_trading_1':
            for t in o['sample_data']['tables']:
                if t['table_name']=='securities':
                    for s in t.get('insert_statements',[]):
                        print(s[:500])
            break
EOF

