        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if job JOB-6007 exists and belongs to GreenLeaf Florist (client_id=6)
    job_query = "SELECT id, client_id, tracking_url, customer_notification_email, customer_notification_phone FROM jobs WHERE id = ?"

    initial_job = safe_query(initial_db_path, job_query, ('JOB-6007',))
    final_job = safe_query(final_db_path, job_query, ('JOB-6007',))

    # Job must exist in both databases
    if not initial_job or not final_job:
        return {"result": "others"}

    initial_job = initial_job[0]
    final_job = final_job[0]

    # Verify job belongs to GreenLeaf Florist (client_id=6)
    if initial_job[1] != 6 or final_job[1] != 6:
        return {"result": "others"}

    # Extract fields from initial and final states
    initial_tracking_url = initial_job[2]
    initial_email = initial_job[3]
    initial_phone = initial_job[4]

    final_tracking_url = final_job[2]
    final_email = final_job[3]
    final_phone = final_job[4]

    # Check that tracking_url was initially NULL or empty
    if initial_tracking_url and initial_tracking_url.strip():
        # If tracking URL already existed, this is not a new creation
        return {"result": "others"}

    # Check that tracking_url is now populated in final database
    if not final_tracking_url or not final_tracking_url.strip():
        return {"result": "others"}

    # Validate tracking_url contains job ID 'JOB-6007'
    if 'JOB-6007' not in final_tracking_url:
        return {"result": "others"}

    # Validate tracking_url appears to be a valid URL format
    # Should start with http:// or https:// or be a path starting with /
    url_pattern = r'^(https?://|/)[\w\-._~:/?#\[\]@!$&\'()*+,;=%]+$'
    if not re.match(url_pattern, final_tracking_url, re.IGNORECASE):
        return {"result": "others"}

    # Verify customer notification fields are populated
    # At least one of email or phone should be present (they were in initial state)
    if not final_email and not final_phone:
        return {"result": "others"}

    # Check that customer notification fields are not empty strings
