ls /tmp/diag/out | grep -Ei 'stock_trading_1|logistics_and_shipment_tracking_1|discussion_forum_2|iot_device_management_3|task_management_16' ; echo ---; python3 -I - <<'EOF'
import sqlite3,glob
checks={
 'stock_trading_1': [("SELECT id,user_id,name FROM watchlists WHERE name='Tech Growth 2025'",()), ("SELECT s.symbol FROM watchlist_items wi JOIN securities s ON s.id=wi.security_id JOIN watchlists w ON w.id=wi.watchlist_id WHERE w.name='Tech Growth 2025'",())],
 'logistics_and_shipment_tracking_1': [("SELECT id,merchant_id,order_reference,status,declared_value,length_cm,width_cm,height_cm,weight_kg FROM shipments WHERE order_reference='ACME-ORD-1001'",())],
 'discussion_forum_2': [("SELECT id,community_id,category_id,title,status FROM threads WHERE title='Saturday Park Cleanup Volunteers Needed'",())],
 'iot_device_management_3': [("SELECT id,version_code,release_channel FROM firmware_versions WHERE version_code='2.3.5' AND release_channel='stable'",())],
 'task_management_16': [("SELECT id,name FROM dashboards WHERE name='Marketing Campaign Overview'",())],
}
for sc in checks:
    ps=glob.glob(f'/tmp/diag/out/{sc}.db')
    if not ps: print(sc,'NO DB YET'); continue
    p=ps[0]; conn=sqlite3.connect(f'file:{p}?mode=ro',uri=True)
    print('###',sc,p)
    for q,args in checks[sc]:
        try: print('  ',q.split('FROM')[0][:60],'->',conn.execute(q,args).fetchall())
        except Exception as e: print('  ERR',e)
    conn.close()
EOF

