python3 -I - <<'EOF'
import json,collections,pyarrow.parquet as pq
D='/workspace/data/AgentWorldModel-1K'
rows=[json.loads(l) for l in open(D+'/gen_verifier.pure_code.jsonl')]
by={}
for r in rows:
    code=r['verification']['code']; by[(r['scenario'],r['task_idx'])]=(code.count('initial_db_path')>1)
res={}
for l in open('/tmp/diag/out/initial_verifier_results.jsonl'):
    r=json.loads(l); res[(r['scenario'],r['task_idx'])]=r
for split in ('train','test'):
    tasks=pq.read_table(f'{D}/verl/{split}.parquet').to_pylist()
    free=0; free_noinit=0; noinit=0
    for row in tasks:
        k=(row['env_kwargs']['scenario'],row['env_kwargs']['task_idx'])
        r=res[k]; f=r['status']=='ok' and r['result']['result']=='complete'
        if not by[k]: noinit+=1
        if f: free+=1; free_noinit += (not by[k])
    print(split,'free',free,'of which verifier ignores initial',free_noinit,'| verifiers ignoring initial',noinit,'/',len(tasks))
EOF

