import json, re
rows=[json.loads(l) for l in open('/workspace/data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl')]
print(list(rows[0]['verification'].keys()))
scan={}
for l in open('/tmp/diag/out/initial_verifier_results.jsonl'):
    r=json.loads(l); scan[(r['scenario'],r['task_idx'])]=r
def body(code):
    lines=code.split('\n'); out=[]; hit=False
    for ln in lines:
        if not hit and re.match(r'\s*def\s+\w+\s*\(', ln):
            hit=True
            m=re.match(r'.*\)\s*(->[^:]*)?:\s*(.*)$', ln)
            out.append(m.group(2) if m else '')
