    b=body(code)
    has='initial_db_path' in b
    s=scan.get((r['scenario'],r['task_idx']))
    res=None
    if s and s['status']=='ok':
        v=s['result']; res=v.get('result') if isinstance(v,dict) else v
    if has: init+=1; init_comp += (res=='complete')
    else: noinit+=1; noinit_comp += (res=='complete')
print('total', len(rows))
print('BODY no initial_db_path', noinit, round(100*noinit/len(rows),1), 'complete-on-init', noinit_comp, round(100*noinit_comp/max(noinit,1),1))
print('BODY uses initial_db_path', init, round(100*init/len(rows),1), 'complete-on-init', init_comp, round(100*init_comp/max(init,1),1))
"

